'use client';

import { useEffect, useState } from 'react';
import { AlertCircle, Loader2, Mail } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible';
import { USER_PASSKEY } from '@/lib/config/user';
import { useToast } from '@/hooks/use-toast';

type SignupPasskeyModalProps = {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onVerified: () => void;
};

export function SignupPasskeyModal({
  open,
  onOpenChange,
  onVerified,
}: SignupPasskeyModalProps) {
  const { toast } = useToast();
  const [passkey, setPasskey] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [requestOpen, setRequestOpen] = useState(false);
  const [requestEmail, setRequestEmail] = useState('');
  const [requestLoading, setRequestLoading] = useState(false);

  useEffect(() => {
    if (!open) return;
    setPasskey('');
    setError(null);
    setRequestOpen(false);
    setRequestEmail('');
  }, [open]);

  const handlePasskeySubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (passkey !== USER_PASSKEY) {
      setError(
        'That passkey is incorrect. Use the passkey from your House of Stole order, or request one below.',
      );
      setPasskey('');
      return;
    }

    setPasskey('');
    onVerified();
  };

  const handleRequestPasskey = async (e: React.FormEvent) => {
    e.preventDefault();
    const email = requestEmail.trim().toLowerCase();
    if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      toast({
        title: 'Invalid email',
        description: 'Enter a valid email address so we can reply.',
        variant: 'destructive',
      });
      return;
    }

    setRequestLoading(true);
    try {
      const res = await fetch('/api/request-passkey', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        toast({
          title: 'Request failed',
          description:
            typeof data?.error === 'string'
              ? data.error
              : 'Something went wrong. Try again later.',
          variant: 'destructive',
        });
        return;
      }
      toast({
        title: 'Request received',
        description:
          typeof data?.message === 'string'
            ? data.message
            : 'If your email is on file, we will send access instructions.',
      });
      setRequestEmail('');
    } catch {
      toast({
        title: 'Network error',
        description: 'Could not send your request. Check your connection.',
        variant: 'destructive',
      });
    } finally {
      setRequestLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className='sm:max-w-md max-h-[90vh] overflow-y-auto'>
        <DialogHeader>
          <DialogTitle>Access Grad Drive sign-up</DialogTitle>
          <DialogDescription>
            Grad Drive accounts are for eligible graduates (for example, through
            your House of Stole order). Enter your access passkey to open the
            sign-up form. If you already have an account, use Log in instead—no
            passkey needed.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handlePasskeySubmit} className='space-y-4'>
          {error ? (
            <Alert variant='destructive' className='rounded-xl'>
              <AlertCircle className='h-4 w-4' />
              <AlertTitle>Incorrect passkey</AlertTitle>
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          ) : null}
          <div className='space-y-2'>
            <Label htmlFor='signup-passkey'>Passkey</Label>
            <Input
              id='signup-passkey'
              type='password'
              placeholder='Enter your passkey'
              value={passkey}
              onChange={(e) => {
                setPasskey(e.target.value);
                setError(null);
              }}
              required
              autoComplete='off'
              className='rounded-xl'
            />
          </div>
          <Button
            type='submit'
            className='w-full rounded-xl font-semibold bg-accent text-accent-foreground hover:bg-accent/90'
          >
            Continue to sign up
          </Button>
        </form>

        <Collapsible open={requestOpen} onOpenChange={setRequestOpen}>
          <CollapsibleTrigger asChild>
            <Button
              type='button'
              variant='ghost'
              className='w-full text-sm text-muted-foreground hover:text-foreground'
            >
              Don&apos;t have a passkey?
            </Button>
          </CollapsibleTrigger>
          <CollapsibleContent className='pt-2'>
            <div className='rounded-xl border border-border bg-muted/40 p-4 space-y-3'>
              <p className='text-sm text-muted-foreground leading-relaxed'>
                Request an access passkey by email. We will send instructions to
                the address you enter if it matches our records.
              </p>
              <form onSubmit={handleRequestPasskey} className='space-y-3'>
                <div className='space-y-2'>
                  <Label htmlFor='passkey-request-email'>Your email</Label>
                  <Input
                    id='passkey-request-email'
                    type='email'
                    placeholder='you@example.com'
                    value={requestEmail}
                    onChange={(e) => setRequestEmail(e.target.value)}
                    required
                    className='rounded-xl'
                    autoComplete='email'
                  />
                </div>
                <Button
                  type='submit'
                  variant='secondary'
                  className='w-full rounded-xl gap-2'
                  disabled={requestLoading}
                >
                  {requestLoading ? (
                    <>
                      <Loader2 className='h-4 w-4 animate-spin' />
                      Sending…
                    </>
                  ) : (
                    <>
                      <Mail className='h-4 w-4' />
                      Request passkey by email
                    </>
                  )}
                </Button>
              </form>
            </div>
          </CollapsibleContent>
        </Collapsible>
      </DialogContent>
    </Dialog>
  );
}
